 <!DOCTYPE html>
 <html lang="pl">
 <head>
   <meta charset="UTF-8" />
   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
   <title>SVG Lampa – Włączanie plафона</title>
   <script src="https://cdn.tailwindcss.com"></script>
   <style>
     .svg-lamp {
       cursor: pointer;
       user-select: none;
     }

     /* Плафон в выключенном и включённом состоянии (250 ms, ease-in-out) */
     .svg-lamp .diffuser-core {
       opacity: 0.12;
       transition: opacity 250ms cubic-bezier(0.4, 0, 0.2, 1);
     }

     .svg-lamp .diffuser-beam {
       opacity: 0;
       transform: scale(0.92);
       transform-origin: 555px 745px;
       transition: opacity 250ms cubic-bezier(0.4, 0, 0.2, 1),
                   transform 500ms ease-out;
     }

     .svg-lamp.is-lit .diffuser-core {
       opacity: 1;
     }

     .svg-lamp.is-lit .diffuser-beam {
       opacity: 1;
       transform: scale(1.06);
     }

     .svg-lamp.is-lit svg {
       filter: drop-shadow(0 18px 36px rgba(255, 206, 105, 0.45));
     }

     .svg-lamp svg {
       transition: filter 250ms cubic-bezier(0.4, 0, 0.2, 1);
     }
   </style>
 </head>
 <body class="bg-[#181512] min-h-screen flex items-center justify-center p-6">

